-- Fixture schema for @phaseo/db tests. Shapes mirror real Phaseo tables
-- (v2_models/v2_labs, workspace_members, workspace_join_requests, ...)
-- in miniature.

create role anon nologin;
create role authenticated nologin;
create role service_role nologin bypassrls;

create schema auth;
create table auth.users (id uuid primary key, email text);

-- Same contract as database/planetscale/migrations/0000_platform.sql:
-- auth.uid()/auth.role()/auth.jwt() read request.jwt.claims like PostgREST sets it.
create function auth.jwt() returns jsonb language sql stable as $$
  select coalesce(nullif(current_setting('request.jwt.claims', true), ''), '{}')::jsonb
$$;
create function auth.uid() returns uuid language sql stable as $$
  select nullif(auth.jwt() ->> 'sub', '')::uuid
$$;
create function auth.role() returns text language sql stable as $$
  select nullif(auth.jwt() ->> 'role', '')
$$;

create table public.labs (
  lab_slug text primary key,
  name text not null,
  country_code text,
  metadata jsonb not null default '{}'
);

create table public.models (
  model_slug text primary key,
  name text not null,
  lab_slug text not null constraint models_lab_slug_fkey references public.labs(lab_slug),
  previous_model_slug text constraint models_previous_model_slug_fkey references public.models(model_slug),
  status text not null default 'active',
  hidden boolean not null default false,
  released_at timestamptz,
  input_modalities text[] not null default '{}',
  metadata jsonb,
  created_at timestamptz not null default '2026-01-01T00:00:00Z'
);

-- one-to-one (FK columns are the PK)
create table public.model_details (
  model_slug text primary key references public.models(model_slug),
  notes text
);

create table public.benchmarks (
  benchmark_id text primary key,
  name text not null
);

create table public.benchmark_results (
  result_id bigint primary key,
  model_slug text not null references public.models(model_slug),
  benchmark_id text not null constraint benchmark_results_benchmark_id_fkey references public.benchmarks(benchmark_id),
  score numeric not null,
  effective_to timestamptz
);

-- many-to-many through a junction whose PK is both FKs
create table public.tags (tag_id text primary key, label text not null);
create table public.model_tags (
  model_slug text references public.models(model_slug),
  tag_id text references public.tags(tag_id),
  primary key (model_slug, tag_id)
);

create table public.users (
  user_id uuid primary key,
  display_name text,
  email text unique
);

create table public.workspaces (
  id uuid primary key,
  name text not null,
  slug text unique
);

create table public.workspace_members (
  workspace_id uuid references public.workspaces(id),
  user_id uuid references public.users(user_id),
  role text not null default 'member',
  last_accessed_at timestamptz,
  primary key (workspace_id, user_id)
);

-- two FKs to the same table: embedding users needs a !hint
create table public.workspace_join_requests (
  id uuid primary key,
  workspace_id uuid not null references public.workspaces(id),
  requester_user_id uuid not null constraint workspace_join_requests_requester_user_id_fkey references public.users(user_id),
  decided_by uuid constraint workspace_join_requests_decided_by_fkey references public.users(user_id),
  status text not null default 'pending',
  created_at timestamptz not null default '2026-01-01T00:00:00Z'
);

-- generic shapes: upserts, counters, arrays, json
create table public.events (
  id bigint generated by default as identity primary key,
  kind text not null,
  payload jsonb,
  labels text[],
  amount_nanos bigint,
  occurred_at timestamptz not null default '2026-01-01T00:00:00Z'
);
create table public.settings (
  workspace_id uuid not null,
  key text not null,
  value jsonb,
  updated_count int not null default 0,
  unique (workspace_id, key)
);

-- RLS: each user only sees and writes their own notes.
create table public.notes (
  id bigint generated by default as identity primary key,
  user_id uuid not null default auth.uid(),
  body text not null
);
alter table public.notes enable row level security;
create policy notes_select on public.notes for select to authenticated using (user_id = (select auth.uid()));
create policy notes_insert on public.notes for insert to authenticated with check (user_id = (select auth.uid()));
create policy notes_update on public.notes for update to authenticated using (user_id = (select auth.uid())) with check (user_id = (select auth.uid()));
create policy notes_delete on public.notes for delete to authenticated using (user_id = (select auth.uid()));

-- A trigger that only lets service_role change a column (like
-- protect_data_contribution_settings in prod).
create table public.protected_settings (
  id int primary key,
  locked_value text
);
create function public.protect_locked_value() returns trigger language plpgsql as $$
begin
  if new.locked_value is distinct from old.locked_value and coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'only service_role may change locked_value' using errcode = '42501';
  end if;
  return new;
end $$;
create trigger protect_locked_value before update on public.protected_settings for each row execute function public.protect_locked_value();

-- Real-shaped tables for the call-site tests
create table public.oauth_authorizations (
  id uuid primary key,
  client_id text not null,
  user_id uuid not null references public.users(user_id),
  workspace_id uuid references public.workspaces(id),
  revoked_at timestamptz,
  last_used_at timestamptz
);
create table public.api_apps (id uuid primary key, app_key text not null, title text);
create table public.gateway_requests (
  request_id text primary key,
  workspace_id uuid not null,
  created_at timestamptz not null,
  app_id uuid constraint gateway_requests_app_id_fkey references public.api_apps(id),
  detail_metadata jsonb,
  cost_nanos bigint
);
create table public.v2_model_provider_routes (
  provider_model_id text primary key,
  provider_slug text not null,
  model_slug text not null,
  provider_model_slug text,
  status text not null,
  routing_enabled boolean not null default true
);
create table public.v2_pricing_skus (
  sku_id text primary key,
  provider_model_id text not null references public.v2_model_provider_routes(provider_model_id),
  operation text not null,
  status text not null,
  currency text not null,
  effective_from timestamptz not null,
  effective_to timestamptz
);
create table public.v2_pricing_sku_meters (
  sku_meter_id text primary key,
  sku_id text not null references public.v2_pricing_skus(sku_id),
  meter_key text not null,
  price_nanos bigint not null,
  meter_order int not null,
  billable boolean not null default true
);
create table public.broadcast_event_receipts (event_id text primary key, claimed_at timestamptz not null default '2026-01-01T00:00:00Z');

-- Functions (RPC)
create function public.get_lab_models(p_lab text) returns setof public.models language sql stable as $$
  select * from public.models where lab_slug = p_lab order by model_slug
$$;
create function public.count_models(p_lab text default null) returns integer language sql stable as $$
  select count(*)::int from public.models where p_lab is null or lab_slug = p_lab
$$;
create function public.model_names() returns setof text language sql stable as $$
  select model_slug from public.models order by model_slug
$$;
create function public.echo_json(p jsonb) returns jsonb language sql immutable as $$ select p $$;
create function public.sum_array(p_values bigint[]) returns bigint language sql immutable as $$
  select coalesce(sum(v), 0)::bigint from unnest(p_values) v
$$;
create function public.touch_models(p_slugs text[]) returns void language sql as $$
  update public.models set status = 'touched' where model_slug = any(p_slugs)
$$;
create function public.lab_summary(p_lab text) returns table(lab_slug text, model_count bigint) language sql stable as $$
  select l.lab_slug, count(m.model_slug) from public.labs l left join public.models m on m.lab_slug = l.lab_slug
  where l.lab_slug = p_lab group by l.lab_slug
$$;
create function public.single_lab(p_lab text) returns public.labs language sql stable as $$
  select * from public.labs where lab_slug = p_lab
$$;
create function public.whoami() returns uuid language sql stable as $$ select auth.uid() $$;
create function public.current_role_name() returns text language sql stable as $$ select current_user::text $$;
create function public.overloaded(a int) returns text language sql immutable as $$ select 'int' $$;
create function public.overloaded(a text, b text) returns text language sql immutable as $$ select 'text,text' $$;
create function public.fail_with(p_code text) returns void language plpgsql as $$
begin
  raise exception 'failed on purpose' using errcode = p_code, detail = 'some detail', hint = 'some hint';
end $$;
create function public.claim_next_event(p_kind text) returns public.events language sql as $$
  update public.events set kind = kind || ':claimed' where id = (select id from public.events where kind = p_kind order by id limit 1) returning *
$$;

grant usage on schema public, auth to anon, authenticated, service_role;
grant all on all tables in schema public to authenticated, service_role;
grant select on public.labs, public.models to anon;
grant execute on all functions in schema public, auth to anon, authenticated, service_role;

